SELECT d.id, 'en', 'Two regimes, and which fact comes from which', '[["Swiss VAT law, by treaty", "The treaty of 28 October 1994 makes Swiss VAT substance applicable, but through Liechtenstein''s own VAT Act (LGBl 2009 Nr. 330). B2B, B2C, e-reporting and the signature position all sit here."], ["Liechtenstein''s own administration", "Competence follows seat, not turnover: a Liechtenstein-seated business files with the Liechtenstein Steuerverwaltung and never with the Swiss FTA. Import VAT is the exception and is administered on the Swiss side."], ["The EEA Agreement, for procurement", "Annex XVI covers public procurement, which is how Directive 2014/55/EU reached a non-EU state. The B2G answer is genuinely Liechtenstein''s own."], ["What this asymmetry predicts", "Indirect taxation is expressly outside the EEA Agreement. ViDA and any future EU B2B or digital reporting requirement will not propagate here. European procurement instruments will."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Dos regímenes, y de cuál procede cada hecho', '[["Ley suiza del IVA, por tratado", "El tratado de 28 de octubre de 1994 hace aplicable la sustancia del IVA suizo, pero a través de la Ley del IVA propia de Liechtenstein (LGBl 2009 Nr. 330). B2B, B2C, e-reporting y la firma se sitúan aquí."], ["Administración propia de Liechtenstein", "La competencia sigue al domicilio, no al volumen: una empresa con sede en Liechtenstein declara ante la Steuerverwaltung de Liechtenstein y nunca ante la administración suiza. El IVA a la importación es la excepción y se administra del lado suizo."], ["El Acuerdo EEE, para la contratación", "El anexo XVI cubre la contratación pública, y así llegó la Directiva 2014/55/UE a un Estado no perteneciente a la UE. La respuesta B2G es genuinamente propia de Liechtenstein."], ["Qué predice esta asimetría", "La fiscalidad indirecta queda expresamente fuera del Acuerdo EEE. ViDA y cualquier futuro requisito europeo B2B o de declaración digital no se propagarán aquí. Los instrumentos europeos de contratación sí."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Zwei Regime, und woher welche Tatsache stammt', '[["Schweizerisches MWST-Recht, kraft Staatsvertrag", "Der Staatsvertrag vom 28. Oktober 1994 macht schweizerische MWST-Substanz anwendbar, jedoch über Liechtensteins eigenes MWSTG (LGBl 2009 Nr. 330). B2B, B2C, E-Reporting und die Signaturfrage liegen hier."], ["Liechtensteins eigene Verwaltung", "Die Zuständigkeit folgt dem Sitz, nicht dem Umsatz: ein in Liechtenstein ansässiges Unternehmen rechnet mit der liechtensteinischen Steuerverwaltung ab und nie mit der ESTV. Die Einfuhrsteuer ist die Ausnahme und wird schweizerisch verwaltet."], ["Das EWR-Abkommen, für die Beschaffung", "Anhang XVI erfasst das öffentliche Beschaffungswesen; so erreichte die Richtlinie 2014/55/EU einen Nicht-EU-Staat. Die B2G-Antwort ist wirklich Liechtensteins eigene."], ["Was diese Asymmetrie voraussagt", "Die indirekte Besteuerung liegt ausdrücklich ausserhalb des EWR-Abkommens. ViDA und jede künftige EU-Pflicht zu B2B oder digitaler Meldung werden hier nicht ankommen. Europäische Beschaffungsinstrumente schon."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Deux régimes, et d''où vient chaque fait', '[["Droit suisse de la TVA, par traité", "Le traité du 28 octobre 1994 rend applicable la substance de la TVA suisse, mais à travers la loi TVA propre au Liechtenstein (LGBl 2009 Nr. 330). B2B, B2C, e-reporting et la question de la signature relèvent d''ici."], ["L''administration propre au Liechtenstein", "La compétence suit le siège et non le chiffre d''affaires : une entreprise établie au Liechtenstein déclare auprès de la Steuerverwaltung locale et jamais auprès de l''administration suisse. La TVA à l''importation fait exception et relève du côté suisse."], ["L''accord EEE, pour la commande publique", "L''annexe XVI couvre les marchés publics ; c''est ainsi que la directive 2014/55/UE a atteint un État non membre de l''UE. La réponse B2G est véritablement celle du Liechtenstein."], ["Ce que cette asymétrie prédit", "La fiscalité indirecte est expressément hors de l''accord EEE. ViDA et toute future exigence européenne B2B ou de déclaration numérique ne s''y propageront pas. Les instruments européens de commande publique, si."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 0;

