SELECT d.id, 'en', '⚠️ "No B2G mandate" is quoted out of context', '[["What the Commission says", "Its country page states that Liechtenstein does not have a B2G e-invoicing mandate — meaning no duty on suppliers to SEND — and asserts the authorities'' duty to RECEIVE on the same page."], ["How it gets re-quoted", "The first half circulates on vendor trackers as though Liechtenstein had no B2G obligation at all. It has one; it simply falls on the buyer."], ["Why the difference matters to you", "If you supply the Liechtenstein administration you may invoice electronically and be confident it can be received and processed. That assurance is the whole point of the directive, and it is what a bare \"no mandate\" would hide."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', '⚠️ «Sin obligación B2G» se cita fuera de contexto', '[["Qué dice la Comisión", "Su ficha de país afirma que Liechtenstein no tiene una obligación B2G de facturación electrónica —es decir, ningún deber del proveedor de ENVIAR— y en la misma página sostiene el deber del organismo de RECIBIR."], ["Cómo se recita", "La primera mitad circula en los rastreadores de proveedores como si Liechtenstein no tuviera obligación B2G alguna. La tiene; simplemente recae en el comprador."], ["Por qué le importa la diferencia", "Si suministra a la administración de Liechtenstein, puede facturar electrónicamente con la seguridad de que podrá recibirse y procesarse. Esa garantía es el sentido de la directiva, y es lo que un escueto «sin obligación» ocultaría."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', '⚠️ «Keine B2G-Pflicht» wird aus dem Zusammenhang zitiert', '[["Was die Kommission sagt", "Ihre Länderseite hält fest, Liechtenstein habe keine B2G-E-Rechnungs-Pflicht — gemeint ist: keine Pflicht des Lieferanten zu SENDEN — und behauptet auf derselben Seite die Pflicht der Behörde zu EMPFANGEN."], ["Wie es weiterzitiert wird", "Die erste Hälfte kursiert auf Anbieter-Trackern, als hätte Liechtenstein überhaupt keine B2G-Pflicht. Es hat eine; sie trifft nur den Käufer."], ["Warum der Unterschied für Sie zählt", "Wer die liechtensteinische Verwaltung beliefert, darf elektronisch fakturieren und kann sicher sein, dass die Rechnung angenommen und verarbeitet wird. Genau diese Zusicherung ist der Zweck der Richtlinie — und das, was ein blosses «keine Pflicht» verdecken würde."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', '⚠️ « Aucune obligation B2G » est citée hors contexte', '[["Ce que dit la Commission", "Sa fiche pays indique que le Liechtenstein n''a pas d''obligation B2G de facturation électronique — soit aucune obligation pour le fournisseur d''ÉMETTRE — et affirme sur la même page l''obligation du pouvoir adjudicateur de RECEVOIR."], ["Comment elle est reprise", "La première moitié circule sur les trackers d''éditeurs comme si le Liechtenstein n''avait aucune obligation B2G. Il en a une ; elle pèse simplement sur l''acheteur."], ["Pourquoi la nuance compte", "Si vous fournissez l''administration liechtensteinoise, vous pouvez facturer par voie électronique avec l''assurance que la facture sera reçue et traitée. Cette assurance est tout l''objet de la directive, et c''est ce qu''un simple « aucune obligation » masquerait."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'scope_transmission' AND d.sort_order = 1;

INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT c.id, 'file_format', 0 FROM countries c WHERE c.code = 'LI'
  AND NOT EXISTS (SELECT 1 FROM deep_dive_cards d WHERE d.country_id = c.id AND d.section = 'file_format' AND d.sort_order = 0);
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Format, transmission and what does not exist', '[["Standard", "EN 16931, as the directive requires. No national CIUS is in effect; the Commission notes a draft addressing VAT requirements, whose status is not published."], ["Transmission", "By email to the contracting authority, in XML or PDF. There is no national e-invoicing platform and no central access point."], ["Peppol", "No Peppol Authority in Liechtenstein, and none in Switzerland. Where no national authority exists OpenPeppol acts as authority, so commercial use is possible without any domestic governance behind it."], ["Threshold", "The receive obligation is expressed as applying above EU procurement thresholds. The applicable figures are not stated in the sources consulted."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Formato, transmisión y lo que no existe', '[["Norma", "EN 16931, según exige la directiva. No hay CIUS nacional en vigor; la Comisión menciona un borrador sobre requisitos de IVA cuyo estado no está publicado."], ["Transmisión", "Por correo electrónico al organismo contratante, en XML o PDF. No hay plataforma nacional de facturación electrónica ni punto de acceso central."], ["Peppol", "Sin autoridad Peppol en Liechtenstein, y ninguna en Suiza. Donde no hay autoridad nacional, OpenPeppol actúa como tal, de modo que el uso comercial es posible sin gobernanza nacional detrás."], ["Umbral", "La obligación de recepción se expresa como aplicable por encima de los umbrales de contratación de la UE. Las cifras aplicables no constan en las fuentes consultadas."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Format, Übertragung und was es nicht gibt', '[["Standard", "EN 16931, wie von der Richtlinie verlangt. Eine nationale CIUS gilt nicht; die Kommission erwähnt einen Entwurf zu MWST-Anforderungen, dessen Stand nicht veröffentlicht ist."], ["Übertragung", "Per E-Mail an den Auftraggeber, als XML oder PDF. Eine nationale E-Rechnungs-Plattform und einen zentralen Zugangspunkt gibt es nicht."], ["Peppol", "Keine Peppol-Behörde in Liechtenstein und keine in der Schweiz. Wo keine nationale Behörde besteht, handelt OpenPeppol als Behörde, sodass kommerzielle Nutzung ohne nationale Governance möglich ist."], ["Schwellenwert", "Die Empfangspflicht gilt oberhalb der EU-Beschaffungsschwellen. Die massgeblichen Beträge werden in den herangezogenen Quellen nicht genannt."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Format, transmission et ce qui n''existe pas', '[["Norme", "EN 16931, comme l''exige la directive. Aucun CIUS national n''est en vigueur ; la Commission mentionne un projet portant sur les exigences de TVA, dont le statut n''est pas publié."], ["Transmission", "Par courriel au pouvoir adjudicateur, en XML ou en PDF. Il n''existe ni plateforme nationale de facturation électronique ni point d''accès central."], ["Peppol", "Aucune autorité Peppol au Liechtenstein, ni en Suisse. En l''absence d''autorité nationale, OpenPeppol fait office d''autorité : l''usage commercial est donc possible sans gouvernance nationale."], ["Seuil", "L''obligation de réception s''applique au-dessus des seuils de la commande publique de l''UE. Les montants applicables ne figurent pas dans les sources consultées."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'file_format' AND d.sort_order = 0;

INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT c.id, 'penalties_related', 0 FROM countries c WHERE c.code = 'LI'
  AND NOT EXISTS (SELECT 1 FROM deep_dive_cards d WHERE d.country_id = c.id AND d.section = 'penalties_related' AND d.sort_order = 0);
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Retention, which is the obligation that actually binds you', '[["Ten years", "From the end of the financial year of the last entries, under PGR Art. 1059, and separately until absolute prescription of the tax claim under the VAT Act, which is ten years after the end of the tax period."], ["Twenty years", "For records concerning immovable property."], ["Electronic retention", "Permitted. Records must not be alterable undetectably and must remain readable at any time; annual accounts and reports stay in written, signed form."], ["Signatures", "Named in the ordinance as one example of assuring integrity, alongside others. Time stamps and audit logs must be retained on the same terms as the records they cover."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Conservación, que es la obligación que de verdad le vincula', '[["Diez años", "Desde el cierre del ejercicio de los últimos asientos, según el art. 1059 PGR, y por separado hasta la prescripción absoluta del crédito tributario según la Ley del IVA, diez años tras el fin del periodo impositivo."], ["Veinte años", "Para los registros relativos a bienes inmuebles."], ["Archivo electrónico", "Permitido. Los registros no deben poder alterarse de forma inadvertida y han de seguir siendo legibles en todo momento; las cuentas e informes anuales se mantienen en forma escrita y firmada."], ["Firmas", "El reglamento las cita como un ejemplo de garantizar la integridad, junto a otros. Los sellos de tiempo y los registros de auditoría se conservan en las mismas condiciones que los documentos que amparan."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Aufbewahrung, die Pflicht, die Sie tatsächlich bindet', '[["Zehn Jahre", "Ab Ende des Geschäftsjahres der letzten Eintragungen nach Art. 1059 PGR und daneben bis zur absoluten Verjährung der Steuerforderung nach dem MWSTG, zehn Jahre nach Ablauf der Steuerperiode."], ["Zwanzig Jahre", "Für Unterlagen im Zusammenhang mit Grundstücken."], ["Elektronische Aufbewahrung", "Zulässig. Aufzeichnungen dürfen nicht unbemerkt änderbar sein und müssen jederzeit lesbar bleiben; Jahresrechnung und Berichte bleiben schriftlich und unterzeichnet."], ["Signaturen", "In der Verordnung als ein Beispiel der Integritätssicherung neben anderen genannt. Zeitstempel und Prüfprotokolle sind unter denselben Bedingungen aufzubewahren wie die Unterlagen, die sie betreffen."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'La conservation, qui est l''obligation qui vous lie réellement', '[["Dix ans", "À compter de la clôture de l''exercice des dernières écritures, selon l''art. 1059 PGR, et séparément jusqu''à la prescription absolue de la créance fiscale selon la loi TVA, dix ans après la fin de la période fiscale."], ["Vingt ans", "Pour les documents relatifs aux biens immobiliers."], ["Archivage électronique", "Admis. Les documents ne doivent pas pouvoir être modifiés de façon indétectable et doivent rester lisibles à tout moment ; comptes et rapports annuels demeurent écrits et signés."], ["Signatures", "L''ordonnance les cite comme un exemple d''assurance de l''intégrité, parmi d''autres. Horodatages et journaux d''audit se conservent aux mêmes conditions que les documents qu''ils couvrent."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 0;

INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT c.id, 'penalties_related', 1 FROM countries c WHERE c.code = 'LI'
  AND NOT EXISTS (SELECT 1 FROM deep_dive_cards d WHERE d.country_id = c.id AND d.section = 'penalties_related' AND d.sort_order = 1);
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', '🔍 What we could not confirm', '[["The article imposing the receive duty", "The Commission attributes it to Article 44a of the procurement act; Article 44a is about consulting trade associations, and the Act truncates on retrieval. What is confirmed is Article 1a, which lists Directive 2014/55/EU as implemented, and Article 7, which carries its definitions."], ["The transposition date in national law", "A consolidated version of the procurement act commences on 27 November 2018, the EEA compliance date. The coincidence is compelling and the amending text could not be read."], ["The 1994 treaty''s own text", "Its name, date and reference are confirmed from the VAT Act and the 2012 supplementing agreement. The treaty text itself is served by a JavaScript-only site and could not be retrieved."], ["The national CIUS", "The Commission says none is applied but that a draft addressing VAT requirements exists. Author, status and timeline unknown."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', '🔍 Lo que no pudimos confirmar', '[["El artículo que impone el deber de recepción", "La Comisión lo atribuye al artículo 44a de la ley de contratación; el 44a trata de la consulta a asociaciones sectoriales, y la ley se trunca al recuperarla. Sí está confirmado el artículo 1a, que enumera la Directiva 2014/55/UE como implementada, y el 7, que recoge sus definiciones."], ["La fecha de transposición en derecho interno", "Una versión consolidada de la ley de contratación entra en vigor el 27 de noviembre de 2018, fecha de cumplimiento en el EEE. La coincidencia es elocuente y el texto modificativo no pudo leerse."], ["El texto del tratado de 1994", "Su nombre, fecha y referencia se confirman por la Ley del IVA y el acuerdo complementario de 2012. El texto del tratado lo sirve un sitio que solo funciona con JavaScript y no pudo recuperarse."], ["El CIUS nacional", "La Comisión dice que no se aplica ninguno, pero que existe un borrador sobre requisitos de IVA. Autoría, estado y calendario desconocidos."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', '🔍 Was wir nicht bestätigen konnten', '[["Der Artikel, der die Empfangspflicht begründet", "Die Kommission schreibt sie Art. 44a des Beschaffungsgesetzes zu; Art. 44a betrifft den Einbezug von Verbänden, und das Gesetz bricht beim Abruf ab. Bestätigt sind Art. 1a, der die Richtlinie 2014/55/EU als umgesetzt aufführt, und Art. 7, der ihre Definitionen trägt."], ["Das Umsetzungsdatum im Landesrecht", "Eine konsolidierte Fassung des Beschaffungsgesetzes tritt am 27. November 2018 in Kraft, dem EWR-Umsetzungstermin. Das Zusammentreffen ist bezeichnend, der ändernde Text war nicht lesbar."], ["Der Text des Staatsvertrags von 1994", "Name, Datum und Fundstelle sind über das MWSTG und die Vereinbarung von 2012 bestätigt. Der Vertragstext selbst wird von einer reinen JavaScript-Seite ausgeliefert und war nicht abrufbar."], ["Die nationale CIUS", "Die Kommission sagt, es werde keine angewendet, es existiere aber ein Entwurf zu MWST-Anforderungen. Urheber, Stand und Zeitplan unbekannt."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', '🔍 Ce que nous n''avons pas pu confirmer', '[["L''article imposant l''obligation de réception", "La Commission l''attribue à l''article 44a de la loi sur les marchés publics ; or l''article 44a porte sur la consultation des associations professionnelles, et la loi est tronquée à la récupération. Sont confirmés l''article 1a, qui énumère la directive 2014/55/UE comme mise en œuvre, et l''article 7, qui en reprend les définitions."], ["La date de transposition en droit interne", "Une version consolidée de la loi entre en vigueur le 27 novembre 2018, date de conformité EEE. La coïncidence est parlante et le texte modificatif n''a pas pu être lu."], ["Le texte du traité de 1994", "Son intitulé, sa date et sa référence sont confirmés par la loi TVA et l''accord complémentaire de 2012. Le texte du traité lui-même est servi par un site uniquement en JavaScript et n''a pas pu être récupéré."], ["Le CIUS national", "La Commission indique qu''aucun n''est appliqué, mais qu''un projet portant sur les exigences de TVA existe. Auteur, statut et calendrier inconnus."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'LI') AND d.section = 'penalties_related' AND d.sort_order = 1;

-- ---- steps ----
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT c.id, 0 FROM countries c WHERE c.code = 'LI'
  AND NOT EXISTS (SELECT 1 FROM deep_dive_steps d WHERE d.country_id = c.id AND d.sort_order = 0);
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'en', 'Confirm which administration you deal with', 'Competence follows your seat, not your turnover. A Liechtenstein-seated business files domestic VAT with the Liechtenstein Steuerverwaltung; a business seated elsewhere in the joint territory files with the Swiss FTA. Import VAT is administered on the Swiss side either way.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'es', 'Confirme con qué administración trata', 'La competencia sigue a su domicilio, no a su volumen. Una empresa con sede en Liechtenstein declara el IVA interno ante la Steuerverwaltung de Liechtenstein; una con sede en el resto del territorio común lo hace ante la administración suiza. El IVA a la importación se administra del lado suizo en ambos casos.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'de', 'Klären Sie, mit welcher Verwaltung Sie es zu tun haben', 'Die Zuständigkeit folgt Ihrem Sitz, nicht Ihrem Umsatz. Ein in Liechtenstein ansässiges Unternehmen rechnet die Inland-MWST mit der liechtensteinischen Steuerverwaltung ab, ein im übrigen Anwendungsgebiet ansässiges mit der ESTV. Die Einfuhrsteuer wird in beiden Fällen schweizerisch verwaltet.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'fr', 'Confirmez l''administration dont vous relevez', 'La compétence suit votre siège, non votre chiffre d''affaires. Une entreprise établie au Liechtenstein déclare la TVA interne auprès de la Steuerverwaltung locale ; une entreprise établie ailleurs dans le territoire commun déclare auprès de l''administration suisse. La TVA à l''importation relève du côté suisse dans les deux cas.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 0;

INSERT INTO deep_dive_steps (country_id, sort_order) SELECT c.id, 1 FROM countries c WHERE c.code = 'LI'
  AND NOT EXISTS (SELECT 1 FROM deep_dive_steps d WHERE d.country_id = c.id AND d.sort_order = 1);
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'en', 'Get onto eMWST if you have not', 'Filing VAT returns through the portal has been mandatory since January 2025. This is the one Liechtenstein obligation with a recent date on it, and it is administrative rather than substantive — no invoice data is transmitted.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'es', 'Dese de alta en eMWST si aún no lo ha hecho', 'Presentar las declaraciones de IVA por el portal es obligatorio desde enero de 2025. Es la única obligación reciente de Liechtenstein con fecha, y es administrativa y no sustantiva: no se transmite ningún dato de factura.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'de', 'Registrieren Sie sich für eMWST, falls noch nicht geschehen', 'Die MWST-Abrechnung über das Portal ist seit Januar 2025 zwingend. Es ist die einzige liechtensteinische Pflicht mit jüngerem Datum, und sie ist administrativ, nicht materiell — Rechnungsdaten werden nicht übermittelt.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'fr', 'Inscrivez-vous à eMWST si ce n''est pas fait', 'Déposer les déclarations de TVA par le portail est obligatoire depuis janvier 2025. C''est la seule obligation liechtensteinoise récemment datée, et elle est administrative et non substantielle : aucune donnée de facture n''est transmise.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 1;

INSERT INTO deep_dive_steps (country_id, sort_order) SELECT c.id, 2 FROM countries c WHERE c.code = 'LI'
  AND NOT EXISTS (SELECT 1 FROM deep_dive_steps d WHERE d.country_id = c.id AND d.sort_order = 2);
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'en', 'If you supply the administration, consider invoicing electronically anyway', 'You are not required to, but the authority is required to accept and process a compliant invoice. That assurance exists in law and most suppliers never use it.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'es', 'Si suministra a la administración, plantéese facturar electrónicamente igualmente', 'No está obligado, pero el organismo sí lo está a aceptar y procesar una factura conforme. Esa garantía existe en la ley y la mayoría de los proveedores nunca la usa.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'de', 'Wer die Verwaltung beliefert, sollte elektronische Rechnungen dennoch erwägen', 'Sie müssen nicht, aber der Auftraggeber muss eine konforme Rechnung annehmen und verarbeiten. Diese Zusicherung steht im Gesetz, und die meisten Lieferanten nutzen sie nie.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'fr', 'Si vous fournissez l''administration, envisagez tout de même la facture électronique', 'Vous n''y êtes pas tenu, mais le pouvoir adjudicateur est tenu d''accepter et de traiter une facture conforme. Cette assurance existe en droit et la plupart des fournisseurs ne s''en servent jamais.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 2;

INSERT INTO deep_dive_steps (country_id, sort_order) SELECT c.id, 3 FROM countries c WHERE c.code = 'LI'
  AND NOT EXISTS (SELECT 1 FROM deep_dive_steps d WHERE d.country_id = c.id AND d.sort_order = 3);
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'en', 'Know which of your obligations would move, and which would not', 'A future EU B2B or digital reporting mandate cannot reach Liechtenstein: indirect taxation is outside the EEA Agreement. A future European procurement instrument can and would. If you are planning across markets, that is the line to plan against.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'es', 'Sepa cuáles de sus obligaciones se moverían y cuáles no', 'Una futura obligación europea B2B o de declaración digital no puede alcanzar a Liechtenstein: la fiscalidad indirecta queda fuera del Acuerdo EEE. Un futuro instrumento europeo de contratación sí puede y lo haría. Si planifica en varios mercados, esa es la línea sobre la que planificar.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'de', 'Wissen Sie, welche Ihrer Pflichten sich bewegen würden und welche nicht', 'Eine künftige EU-Pflicht zu B2B oder digitaler Meldung kann Liechtenstein nicht erreichen: die indirekte Besteuerung liegt ausserhalb des EWR-Abkommens. Ein künftiges europäisches Beschaffungsinstrument kann und würde es. Wer über Märkte hinweg plant, sollte an dieser Linie planen.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description)
SELECT s.id, 'fr', 'Sachez lesquelles de vos obligations bougeraient, et lesquelles non', 'Une future obligation européenne B2B ou de déclaration numérique ne peut atteindre le Liechtenstein : la fiscalité indirecte est hors de l''accord EEE. Un futur instrument européen de commande publique, si. Si vous planifiez sur plusieurs marchés, c''est la ligne sur laquelle planifier.' FROM deep_dive_steps s WHERE s.country_id = (SELECT id FROM countries WHERE code = 'LI') AND s.sort_order = 3;

